<script setup>
import {copyText} from '../shared/clipboard.js'
import {computed,ref,watch} from 'vue'

import {responseDocument,fieldAssertion,fieldExtraction,expandedResponseRows} from './responseModel.js'
import HelpTip from '../shared/components/HelpTip.vue'
const props=defineProps({body:{type:String,default:''},truncated:Boolean,canAssert:Boolean,canExtract:Boolean})
const emit=defineEmits(['assert','extract'])
const mode=ref('formatted'),search=ref(''),expanded=ref(['']),selected=ref(null),variableName=ref(''),variableError=ref('')
const parsed=computed(()=>responseDocument(props.body))
const rows=computed(()=>search.value?parsed.value.flat.filter(r=>(r.path+' '+r.value).toLowerCase().includes(search.value.toLowerCase())).map(({children,...r})=>r):parsed.value.rows)
watch(()=>props.body,()=>{expanded.value=[''];selected.value=null;variableError.value=''})
function startExtraction(row){selected.value=row;variableName.value=/^[A-Za-z_][A-Za-z0-9_]{0,63}$/.test(row.name)?row.name:'response_value';variableError.value=''}
function extract(){try{emit('extract',fieldExtraction(selected.value,variableName.value));selected.value=null;return true}catch(e){variableError.value=e.message;return false}}
function copy(){return copyText(mode.value==='raw'?props.body:parsed.value.formatted,{successMessage:'响应已复制',failureMessage:'复制失败，可手动选择响应内容'})}



import {Badge,Button,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsList,TabsTrigger} from '../shared/shadcn-ui.js'

const visibleRows=computed(()=>expandedResponseRows(rows.value,expanded.value))
function toggleRow(record){expanded.value=expanded.value.includes(record.key)?expanded.value.filter(key=>key!==record.key):[...expanded.value,record.key]}

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><section class="response-viewer"><div class="response-tools"><Tabs :model-value="mode" @update:model-value="mode=$event;"><TabsList class="h-auto! flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;formatted&quot;">格式化</TabsTrigger><TabsTrigger :disabled="!parsed.valid" :value="&quot;fields&quot;">字段</TabsTrigger><TabsTrigger :value="&quot;raw&quot;">原文</TabsTrigger></TabsList></Tabs><InputGroup v-if="mode==='fields'" style="width:240px" class="min-w-0 "><InputGroupInput  v-model="search" placeholder="搜索字段路径或值" aria-label="搜索响应字段"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><Button v-if="mode==='fields'" @click="expanded=parsed.flat.filter(r=>r.children).map(r=>r.key)" variant="ghost" size="default" type="button">展开全部</Button><Button v-if="mode==='fields'" @click="expanded=[]" variant="ghost" size="default" type="button">收起全部</Button><Button @click="copy" variant="ghost" size="default" type="button">复制响应</Button><Badge v-if="truncated" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">响应已截断，不能据此添加字段断言或提取</Badge><Badge v-if="mode==='fields'&&parsed.limited" variant="secondary">仅展示前 500 个字段 / 16 层</Badge><HelpTip v-if="canAssert||canExtract" text="从已脱敏响应选择字段，不会重新发送请求。敏感 / 遮蔽字段不能作为断言或提取来源；提取只保存字段路径，不保存实际值。"/></div><div v-if="mode==='fields'" class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:650,y:420}).y?({x:650,y:420}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:650,y:420}).x||({x:650,y:420}).minWidth||685)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(250)+'px'}">字段 / JSON Pointer</TableHead><TableHead :style="{width:(85)+'px'}">类型</TableHead><TableHead>值</TableHead><TableHead v-if="canAssert||canExtract" :style="{width:(200)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (visibleRows||[])" :key="typeof (&quot;key&quot;)==='function'?(&quot;key&quot;)(record):record[&quot;key&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><span class="min-w-0 break-words"><span class="inline-flex items-center gap-1" :style="{paddingLeft:record.depth*16+'px'}"><Button v-if="record.children?.length" variant="ghost" size="icon-xs" :aria-label="expanded.includes(record.key)?'收起字段':'展开字段'" @click="toggleRow(record)">{{expanded.includes(record.key)?'−':'+'}}</Button><code>{{record.path||'（根）'}}</code></span></span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["kind"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><code>{{record.value}}</code></template></div></TableCell><TableCell v-if="canAssert||canExtract" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div class="flex flex-wrap items-center gap-2"><Button v-if="canAssert" @click="emit('assert',fieldAssertion(record))" variant="ghost" size="sm" type="button" :disabled="(truncated||!record.canAssert)">添加断言</Button><Button v-if="canExtract" @click="startExtraction(record)" variant="ghost" size="sm" type="button" :disabled="(truncated||!record.canExtract)">提取变量</Button></div></template></div></TableCell></TableRow></template><TableRow v-if="!(visibleRows||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><pre v-else>{{(mode==='raw'?body:parsed.formatted)||'暂无响应正文'}}</pre><Dialog :open="!!selected" @update:open="async v=>{if(!v){selected=null}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (480)==='number'?(480)+'px':(480)}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>提取为步骤变量</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset class="min-w-0 space-y-5" ><Field><FieldLabel>来源字段</FieldLabel><span class="min-w-0 break-words"><code>{{selected?.path||'（根）'}}</code></span></Field><Field><FieldLabel>变量名 <span class="text-destructive">*</span></FieldLabel><Input v-model="variableName" aria-label="响应提取变量名" :maxlength="64" @keydown.enter="extract"/><FieldError v-if="variableError">{{variableError}}</FieldError></Field></fieldset></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button variant="outline" @click="async()=>{selected=null}">取消</Button><Button @click="async()=>{if(await (extract)()!==false){}}">确认</Button></DialogFooter></DialogContent></Dialog></section></template>
<style scoped>.response-viewer{min-width:0}.response-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--mono);font-size:.75rem;background:var(--panel2);padding:12px;max-height:500px;overflow:auto}code{white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--mono);font-size:.75rem}</style>
